"""Rate limiting for the public API: a token bucket per client key."""

from __future__ import annotations

import time
from dataclasses import dataclass, field


@dataclass
class Bucket:
    capacity: int
    refill_per_s: float
    tokens: float = field(init=False)
    updated: float = field(default_factory=time.monotonic)

    def __post_init__(self) -> None:
        self.tokens = float(self.capacity)

    def take(self, n: int = 1) -> bool:
        now = time.monotonic()
        self.tokens = min(self.capacity, self.tokens + (now - self.updated) * self.refill_per_s)
        self.updated = now
        if self.tokens >= n:
            self.tokens -= n
            return True
        return False


class Limiter:
    def __init__(self, capacity: int = 60, refill_per_s: float = 1.0) -> None:
        self.capacity, self.refill = capacity, refill_per_s
        self.buckets: dict[str, Bucket] = {}

    def allow(self, key: str) -> bool:
        bucket = self.buckets.get(key)
        if bucket is None:
            bucket = self.buckets[key] = Bucket(self.capacity, self.refill)
        return bucket.take()


